function demoMain(idx,label){
  var texts=["call me 555-1234","email a@b.com now","no pii here"];
  var t=texts[idx%texts.length];
  var found=t.match(/\d{3}-\d{4}|[\w.]+@[\w.]+/g)||[];
  return "["+label+"] scanned '"+t+"' -> PII hits: "+(found.length?found.join(","):"none");
}

